// ── CONFIGURABLE VARIABLES ──────────────────────────────────────────────
// Edit these three values to match your setup.
const GITHUB_OWNER  = 'octocat';                         // GitHub org or user
const GITHUB_REPO   = 'Hello-World';                     // repository name
const LANGUAGE      = 'EN';                              // 'EN' or 'FR'
const DISCORD_WEBHOOK_URL = 'https://discord.com/api/webhooks/YOUR_WEBHOOK_ID/YOUR_WEBHOOK_TOKEN';
// ────────────────────────────────────────────────────────────────────────────

// Compute ISO date for 7 days ago (GitHub's `since` param)
const since = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString();

return [{
  json: {
    owner:             GITHUB_OWNER,
    repo:              GITHUB_REPO,
    language:          LANGUAGE,
    discordWebhookUrl: DISCORD_WEBHOOK_URL,
    since
  }
}];

// Retrieve outputs from parallel branches
const config   = $('Config Variables').first().json;
const commits  = $('Fetch Commits').all().map(i => i.json);
const allIssues = $('Fetch Closed Issues').all().map(i => i.json);
const allPRs   = $('Fetch Merged PRs').all().map(i => i.json);

const since = new Date(config.since);

// Filter real issues (GitHub returns PRs in /issues endpoint too)
const issues = allIssues.filter(issue => {
  if (issue.pull_request) return false;
  const closed = new Date(issue.closed_at);
  return closed >= since;
});

// Filter only merged PRs closed this week
const prs = allPRs.filter(pr => {
  if (!pr.merged_at) return false;
  const merged = new Date(pr.merged_at);
  return merged >= since;
});

// Build concise summaries to keep the Claude prompt reasonably sized
const commitSummary = commits.slice(0, 50).map(c =>
  `- ${c.commit.message.split('\n')[0]} (${c.author ? c.author.login : 'unknown'})`
).join('\n') || 'No commits this week.';

const issueSummary = issues.slice(0, 30).map(i =>
  `- #${i.number} ${i.title} (closed by ${i.user ? i.user.login : 'unknown'})`
).join('\n') || 'No issues closed this week.';

const prSummary = prs.slice(0, 30).map(p =>
  `- #${p.number} ${p.title} (merged by ${p.merged_by ? p.merged_by.login : 'unknown'})`
).join('\n') || 'No PRs merged this week.';

const langInstruction = config.language === 'FR'
  ? 'Réponds entièrement en français.'
  : 'Reply entirely in English.';

const repo = `${config.owner}/${config.repo}`;
const weekStart = since.toISOString().split('T')[0];
const weekEnd   = new Date().toISOString().split('T')[0];

const prompt = `${langInstruction}

You are a senior engineering writer. Generate a clear, engaging weekly development summary for the GitHub repository **${repo}** covering the period ${weekStart} → ${weekEnd}.

Structure your response with these sections (use Markdown):
1. **Overview** — one-paragraph executive summary of the week's activity.
2. **Commits (${commits.length} total)** — highlight the most significant changes.
3. **Closed Issues (${issues.length} total)** — summarise what was resolved.
4. **Merged Pull Requests (${prs.length} total)** — summarise what shipped.
5. **Key Contributors** — mention active contributors by name.
6. **Looking Ahead** — one sentence of encouragement or focus for next week.

Keep the tone professional yet friendly. Total length: 300–500 words.

---
RAW DATA

### Commits
${commitSummary}

### Closed Issues
${issueSummary}

### Merged PRs
${prSummary}
`;

return [{
  json: {
    prompt,
    discordWebhookUrl: config.discordWebhookUrl,
    repo,
    weekStart,
    weekEnd,
    language: config.language
  }
}];

const claudeResponse = $json;
const prev = $('Aggregate & Build Prompt').first().json;

// Extract text from Claude's response
let summary = '';
if (claudeResponse.content && claudeResponse.content.length > 0) {
  summary = claudeResponse.content[0].text || '';
}

// Discord has a 2000-char limit per message; split if needed
const MAX_LEN = 1900;
const header = `📊 **Weekly Dev Summary — ${prev.repo}** (${prev.weekStart} → ${prev.weekEnd})\n\n`;
const full = header + summary;

const chunks = [];
if (full.length <= MAX_LEN) {
  chunks.push(full);
} else {
  // Always put header in first chunk
  let remaining = full;
  while (remaining.length > 0) {
    chunks.push(remaining.slice(0, MAX_LEN));
    remaining = remaining.slice(MAX_LEN);
  }
}

return chunks.map((content, idx) => ({
  json: {
    content,
    chunkIndex: idx,
    totalChunks: chunks.length,
    discordWebhookUrl: prev.discordWebhookUrl
  }
}));
